<?php require '../../includes/config.php';require '../../includes/layout.php';require_login(['admin']);if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$name=trim($_POST['name']);$email=strtolower(trim($_POST['email']));$password=$_POST['password']??'Dept@123';if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)){try{$stmt=$conn->prepare('INSERT INTO departments(name) VALUES(?)');$stmt->bind_param('s',$name);$stmt->execute();$deptId=$conn->insert_id;$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=$conn->prepare("INSERT INTO users(full_name,email,department_id,password_hash,role) VALUES(?,?,?,?,'department')");$stmt->bind_param('ssis',$name,$email,$deptId,$hash);$stmt->execute();$success='Department and login account created.';}catch(mysqli_sql_exception $e){$error='Department or email already exists.';}}else$error='Enter a valid department name and email.';}$rows=$conn->query('SELECT d.id,d.name,COUNT(u.id) accounts FROM departments d LEFT JOIN users u ON u.department_id=d.id AND u.role="department" GROUP BY d.id,d.name ORDER BY d.name')->fetch_all(MYSQLI_ASSOC);admin_shell('Departments','departments');?><div class="page-header"><h2>Departments</h2></div><?php if(!empty($success))echo'<div class="alert alert-success">'.e($success).'</div>';if(!empty($error))echo'<div class="alert alert-error">'.e($error).'</div>';?><div class="content-card"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div><label class="label">Department Name</label><input name="name" required></div><div><label class="label">Department Login Email</label><input type="email" name="email" required></div><div><label class="label">Password</label><input type="password" name="password" value="Dept@123" minlength="8" required></div></div><button class="btn btn-primary">Create Department Account</button></form></div><div class="content-card table-wrap"><table><thead><tr><th>Department</th><th>Login Accounts</th></tr></thead><tbody><?php foreach($rows as $r)echo'<tr><td>'.e($r['name']).'</td><td>'.(int)$r['accounts'].'</td></tr>';?></tbody></table></div><?php dashboard_footer(); ?>